module sequence_detector #(
    parameter IDLE = 5'b00001,
    parameter S1   = 5'b00010,
    parameter S2   = 5'b00100,
    parameter S3   = 5'b01000,
    parameter S4   = 5'b10000
) (
    input  clk,
    input  rst_n,
    input  data_in,
    output sequence_detected
);

    reg [3:0] current_state;
    reg [3:0] next_state;

    assign sequence_detected = (current_state == 4'b1000) ? 1'b1 : 1'b0;

    always @(*) begin
        case (current_state)
            4'b0000: 
                if (data_in == 1'b1) next_state = 4'b0001; 
                else next_state = 4'b0000; 
            4'b0001: 
                if (data_in == 1'b0) next_state = 4'b0010; 
                else next_state = 4'b0000; 
            4'b0010: 
                if (data_in == 1'b0) next_state = 4'b0100; 
                else next_state = 4'b0000; 
            4'b0100: 
                if (data_in == 1'b1) next_state = 4'b1000; 
                else next_state = 4'b0000; 
            4'b1000: 
                if (data_in == 1'b1) next_state = 4'b0000; 
                else next_state = 4'b0000; 
            default:
                next_state = 4'b0000; 
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) current_state <= 4'b0000; 
        else current_state <= next_state;
    end

endmodule
